import logging
import time
from robot.libraries.BuiltIn import BuiltIn
from robot.api import TestSuiteBuilder
from taf.internal.robot_typecasts import time_to_seconds
from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper
from taf.rfrl.utilities.general import get_formatted_traceback


def get_builtin_value(param_name, default=None):
    """
    Get robot builtin  variable value, default will return if variable not found
    :param param_name: variable name
    :param default: default value to return if variable not available
    """
    return BuiltIn().get_variable_value('${{{}}}'.format(param_name), default)


def set_robot_global_variable(param_name, param_value):
    """
    Set Robot Global Builtin variable.
    :param param_name: variable name
    :param param_value: value
    """
    BuiltIn().set_global_variable('${{{}}}'.format(param_name), param_value)


def set_robot_suite_variable(param_name, param_value):
    """
    Set Robot Builtin variable.
    :param param_name: variable name
    :param param_value: value
    """
    BuiltIn().set_suite_variable('${{{}}}'.format(param_name), param_value)


def set_robot_test_variable(param_name, param_value):
    """
    Set Robot Builtin variable.
    :param param_name: variable name
    :param param_value: value
    """
    BuiltIn().set_test_variable('${{{}}}'.format(param_name), param_value)


def set_robot_tags(*tag_names):
    """
    Set Robot Builtin tag to current test case.
    :param tag_names: tag names
    """
    BuiltIn().set_tags(*tag_names)


def get_all_variables():
    """
    Get all Robot Builtin variables as dictionary.
    :return: dictionary of all Robot Builtin variables
    """
    return BuiltIn().get_variables()


def log_all_variables(level='INFO'):
    """
    Log all Robot Builtin variables.
    :param level: log level
    """
    BuiltIn().log_variables(level=level)


def import_library_to_robot_framework_namespace(name, *args):
    """
    Import library to Robot Framework namespace
    :param name:  path to library
    :param args: list of arguments passed during import ex:

        import_library_to_robot_framework_namespace('taf.collectors.core', 'WITH NAME', 'core')
    """
    return BuiltIn().import_library(name, *args)


def import_resource_to_robot_framework_namespace(name, *args):
    """
    Import resource to Robot Framework namespace
    :param name:  path to resource
    :param args: list of arguments passed during import ex:

        import_resource_to_robot_framework_namespace('taf/rfrl/bts/robot/gnb.robot')
    """
    return BuiltIn().import_resource(name, *args)


def import_variable_file_to_robot_framework_namespace(file_path, *args):
    """
    Import variable file to Robot Framework namespace
    :param file_path:  path to variable file
    :param args: list of arguments passed during import ex:

        import_variable_file_to_robot_framework_namespace('/tmp/variables.py', 'arg1', 'arg2')
    """
    return BuiltIn().import_variables(file_path, *args)


def get_builtin_instance(instance_name, default=None):
    """
    Get Robot Builtin library instance
    :param instance_name:  library instance name
    :param default: return default instance if not available
    """
    return BuiltIn().get_library_instance('{}'.format(instance_name), default)


def get_robot_builtin_instance_and_import_if_needed(name, library_path):
    """
    Try to get library instance created by robot during import. If the instance doesn't exist import given library
    to robot namespace and return created instance.
    :param name: name/alias of library, eg: core
    :param library_path: full path to library, eg: taf.collectors.core
    :return: instance of library
    """
    library_alias = name if name is not None else library_path
    try:
        return get_builtin_instance(library_alias)
    except RuntimeError:
        logging.debug("'{}' library not imported - try to import '{}'".format(library_alias, library_path))
        args = ['WITH NAME', name] if name else []
        import_library_to_robot_framework_namespace(library_path, *args)
        return get_builtin_instance(library_alias)


def run_robot_keyword(name, *args):
    """
    Run robot keyword
    :param name: keyword name
    :param args: list of arguments
    """
    return BuiltIn().run_keyword(name, *args)


def is_dry_run():
    try:
        current_context = _get_robot_context()
        if current_context.dry_run:
            return True
    except Exception:
        pass
    return False


def _get_robot_context():
    try:
        from robot.running.context import EXECUTION_CONTEXTS
        return EXECUTION_CONTEXTS.current
    except Exception:
        pass
    return None


def get_suite_tags_variable(path):
    """
    Get tags from suite file.
    :param path: path to suite file
    :return: list of tags
    """
    suite = TestSuiteBuilder().build(path)
    tests = list(suite.tests)
    tags = []
    for test in tests:
        tags += test.tags
    tags = list(set(tags))
    return tags


def wait_till_succeeds(func, exception_to_catch, interval=30, timeout=300, print_traceback=False,
                       *args, **kwargs):
    """
    Calls the function until it succeeds (does not raise an exception) or the timeout is reached.
    Formats the logs in a Robot Framework friendly way.

    :param func: The function to call.
    :param exception_to_catch: The exception to catch and retry on. Can be a single exception or a tuple of exceptions.
    :param interval: The interval between retries in seconds.
    :param timeout: The maximum time to wait in seconds.
    :param print_traceback: If True, prints the traceback of the caught exception to the log.
    :param args: The positional arguments to pass to the function.
    :param kwargs: The keyword arguments to pass to the function.
    """
    if not isinstance(exception_to_catch, (tuple, list)):
        exception_to_catch = (exception_to_catch,)

    start_time = time.monotonic()
    end_time = start_time + time_to_seconds(time=timeout)
    interval = time_to_seconds(time=interval)
    attempt = 0
    logging.info(f"Calling function {func.__name__} with args={args}, kwargs={kwargs} with timeout {timeout} seconds "
                 f"and interval {interval} seconds")
    with RobotWrapper(
            wrap_name=f"Wait up to {timeout} seconds, checking every {interval} seconds",
            wrap_type="for"
    ) as wrapper:
        while time.monotonic() < end_time:
            attempt += 1
            wrapper.create_level(wrap_name=f"Attempt number: {attempt}", wrap_type="foritem", level=2)
            try:
                return func(*args, **kwargs)
            except exception_to_catch as e:
                logging.info(f"Attempt {attempt} failed")
                if print_traceback:
                    logging.debug("\tDetails: {}".format(get_formatted_traceback(e)))
                current_time = time.monotonic()
                logging.debug("Time elapsed: {:.2f} seconds".format(current_time - start_time))
                logging.debug("Time remaining: {:.2f} seconds".format(end_time - current_time))
                logging.info(f"Waiting {interval} seconds for next attempt...")
                time.sleep(interval)
    raise TimeoutError(f"Function {func.__name__} did not succeed within {timeout} seconds")
